def calcular_frete(peso_kg: float, regiao: str, valor_pedido: float,
                   cupom: str | None = None, expresso: bool = False) -> float:
    # 1. Validação
    if not (0 < peso_kg <= 30):
        raise ValueError("peso_kg deve ser > 0 e <= 30")
    if regiao not in {"S", "SE", "CO", "NE", "N"}:
        raise ValueError("região inválida")
    if valor_pedido < 0:
        raise ValueError("valor_pedido deve ser >= 0")

    # 2. Tarifa base por peso
    if peso_kg <= 1:
        tarifa = 12.00
    elif peso_kg <= 5:
        fracoes = math.ceil(peso_kg - 1)
        tarifa = 12.00 + 3.50 * fracoes
    else:
        fracoes = math.ceil(peso_kg - 5)
        tarifa = 26.00 + 2.80 * fracoes

    # 3. Multiplicador regional
    multiplicadores = {"S": 1.00, "SE": 1.00, "CO": 1.20, "NE": 1.35, "N": 1.50}
    frete = tarifa * multiplicadores[regiao]

    # 4. Expresso
    if expresso:
        frete *= 1.40

    # 5. Frete grátis (cupom totalmente ignorado, inclusive validação)
    if valor_pedido >= 299.90 and not expresso and regiao in {"S", "SE", "CO"}:
        return 0.0

    # 6. Cupons (validação ocorre aqui, após a verificação de frete grátis)
    if cupom is not None and cupom != "":
        cupom = cupom.upper()
        if cupom == "FRETE10":
            frete *= 0.90
        elif cupom == "FRETEMETADE":
            if peso_kg <= 5:
                frete *= 0.50
            # se peso > 5, cupom ignorado
        else:
            raise ValueError("cupom inválido")

    # 7. Frete mínimo
    frete = max(frete, 9.90)

    # 8. Arredondamento comercial (ROUND_HALF_UP)
    resultado = Decimal(str(frete)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return float(resultado)

